const items = $input.all();
const ids = items.map(r => parseInt(r.json['ID']) || 0).filter(n => n > 0);
const dernierID = ids.length > 0 ? Math.max(...ids) : 0;
const tels = items
  .map(r => (r.json['Téléphone'] || '').replace(/\s/g, ''))
  .filter(t => t.length > 0);
return [{ json: { lastID: dernierID, telsExistants: tels } }];

// Fusionner toutes les requêtes Places
const allPlaces = [];
const villeMap = {};

for (const item of $input.all()) {
  const places = item.json.places || [];
  allPlaces.push(...places);
}

// Dédoublonner par téléphone entre toutes les requêtes
const seen = new Set();
const unique = [];
for (const p of allPlaces) {
  const tel = (p.nationalPhoneNumber || '').replace(/\s/g, '');
  const key = tel || (p.displayName && p.displayName.text) || Math.random().toString();
  if (!seen.has(key)) {
    seen.add(key);
    unique.push(p);
  }
}

return [{ json: { places: unique, total_brut: allPlaces.length, total_unique: unique.length } }];

const dernierID = $('Calculer dernier ID').first().json.lastID || 0;
const telsExistants = $('Calculer dernier ID').first().json.telsExistants || [];
const places = $input.first().json.places || [];

const motsCles = [
  'sophrologue','sophrologie','cabinet','therapie','therapeute','therapies',
  'hypnotherapeute','hypnose','naturopathe','coach','coaching','bien-etre',
  'bien etre','sante','certifie','certifiee','rncp','visio','stress',
  'anxiete','sommeil','doula','numerologue','perinatale','perinatalite',
  'specialise','specialisee','relaxation','mindfulness','pleine','conscience',
  'stop','emotions','debordantes','paris','lyon','marseille','bordeaux',
  'toulouse','nantes','lille','strasbourg','rennes','grenoble','nice',
  'montpellier','metz','nancy','centre','nord','sud','est','ouest',
  'rive','droite','gauche','villeneuve','roubaix','neudorf','hautepierre'
];

const cap = s => s.toLowerCase().replace(/\b\w/g, c => c.toUpperCase());

const results = [];
let idCounter = dernierID;

for (const place of places) {
  const tel = (place.nationalPhoneNumber || '').replace(/\s/g, '');
  if (tel && telsExistants.includes(tel)) continue;

  const raw = (place.displayName && place.displayName.text) ? place.displayName.text : '';
  const nomCabinet = raw;

  let nomNettoye = raw.split(/[-|·•,]/)[0].trim();
  const regex = new RegExp('\\b(' + motsCles.join('|') + ')\\b', 'gi');
  nomNettoye = nomNettoye.replace(regex, '').replace(/\s+/g, ' ').trim();
  nomNettoye = cap(nomNettoye);

  const parts = nomNettoye.split(' ').filter(p => p.length > 1);
  const prenom = parts[0] || raw;
  const nom = parts.slice(1).join(' ') || '';

  const adresse = place.formattedAddress || '';
  const cpMatch = adresse.match(/(\d{5})/);
  const dept = cpMatch ? cpMatch[1].substring(0, 2) : '';

  // Détecter la ville depuis l'adresse
  let ville = '';
  const villeMatch = adresse.match(/\d{5}\s+(.+?)(?:,|$)/);
  if (villeMatch) ville = villeMatch[1].trim();

  idCounter++;

  results.push({
    json: {
      'ID': idCounter,
      'Prénom': prenom,
      'Nom': nom,
      'Nom Cabinet': nomCabinet,
      'Ville': ville || '',
      'Dép.': dept,
      'Téléphone': place.nationalPhoneNumber || '',
      'Email': '',
      'Note Google ★': place.rating ? place.rating.toString() : '',
      'Nb Avis': place.userRatingCount ? place.userRatingCount.toString() : '',
      'Site Web': place.websiteUri || '',
      'Bouton Résa ?': 'Non',
      'Source': 'Google Maps',
      'Statut': 'À appeler',
      'Canal Gagnant': '',
      'Date Contact': '',
      'Notes': 'Extrait le ' + new Date().toLocaleDateString('fr-FR')
    }
  });
}

return results;
